const CLIENT_COMPLETE_STATUSES = new Set([
  "submitted",
  "ai_approved",
  "needs_review",
  "staff_approved",
]);

const EXTRACTION_TERMINAL_STATUSES = new Set([
  "extraction_complete",
  "extraction_partial",
  "extraction_failed",
  "ready_for_review",
]);

export function createFamilyMembers(count: number) {
  return Array.from({ length: count }, (_, index) => createFamilyMember(index));
}

export function emptyDocumentBundle(): PassportDocumentBundle {
  return {
    front: null,
    back: null,
    cover: null,
    back_cover: null,
    frontSource: null,
    backSource: null,
    frontManuallyCropped: false,
    backManuallyCropped: false,
  };
}

export function isClientSubmissionComplete(submission: PassportSubmission) {
  return CLIENT_COMPLETE_STATUSES.has(submission.status);
}

export function hasActiveUploadProgress({ step, submission, familyMembers, qualifierSelectionToken, clientName }: {
  step: UploadFlowStep;
  submission: PassportSubmission | null;
  familyMembers: readonly FamilyMember[];
  qualifierSelectionToken: string | null;
  clientName: string;
}) {
  return step !== "SUCCESS" && (
    submission !== null
    || familyMembers.some((member) => member.submission !== null)
    || qualifierSelectionToken !== null
    || clientName.trim().length > 0
    || !PASSIVE_PROGRESS_STEPS.has(step)
  );
}

export function getInitialReviewFields(
  fields: ExtractedPassportFields | null,
) {
  return REVIEW_FIELDS.reduce<Record<string, string>>((current, key) => {
    current[key] = getPassportTextField(fields, key);
    return current;
  }, {});
}

export function passportHolderName(
  fields: ExtractedPassportFields | Record<string, string> | null,
) {
  if (!fields) return "";
  const givenNames = getPassportTextField(
    fields as ExtractedPassportFields,
    "given_names",
  );
  const surname = getPassportTextField(
    fields as ExtractedPassportFields,
    "surname",
  );
  return [givenNames, surname]
    .map((part) => part.trim())
    .filter(Boolean)
    .join(" ");
}

export function mergeMissingReviewFields(
  current: Record<string, string>,
  fields: ExtractedPassportFields | null,
) {
  return REVIEW_FIELDS.reduce<Record<string, string>>((next, key) => {
    const value = getPassportTextField(fields, key);
    if (value.trim() && !next[key]?.trim()) {
      next[key] = value;
    }
    return next;
  }, { ...current });
}

export function isExtractionTerminal(submission: PassportSubmission) {
  return EXTRACTION_TERMINAL_STATUSES.has(submission.extraction_status)
    || submission.status === "ready_for_client_review"
    || submission.status === "review_required"
    || submission.status === "failed";
}

export function extractionNoticeFor(submission: PassportSubmission) {
  if (submission.manual_review_submission_allowed) {
    if (submission.processing_stage === "extraction_busy") {
      return "Extraction is busy. Your passport images are saved. Fill in the details manually; AI verification will check them after you submit.";
    }
    return "Automatic reading is unavailable. Enter the details manually and submit them. AI verification will check them against your saved passport images.";
  }
  if (submission.extraction_status === "extraction_failed" || submission.status === "failed") {
    return "Automatic passport reading failed. Your saved images are safe. Retry reading or replace the image if it could not be verified as the correct passport page.";
  }
  if (submission.extraction_status === "extraction_partial") {
    return "Your passport pages were saved. Some details could not be read confidently, so check and complete the missing fields manually.";
  }
  return null;
}

export function canRetryExtractionFor(submission: PassportSubmission) {
  return submission.extraction_status === "extraction_failed" || submission.status === "failed";
}

export function formatFileSize(bytes: number) {
  if (!Number.isFinite(bytes) || bytes <= 0) return "Size unavailable";
  if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(bytes < 10 * 1024 * 1024 ? 1 : 0)} MB`;
}

export function sleep(delayMs: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal.aborted) {
      reject(new DOMException("Operation cancelled", "AbortError"));
      return;
    }
    const timer = window.setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, delayMs);
    const onAbort = () => {
      window.clearTimeout(timer);
      reject(new DOMException("Operation cancelled", "AbortError"));
    };
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

const PROCESSING_STAGE_LABELS: Readonly<Record<string, string>> = {
  queued: "Your passport extraction is queued and will begin shortly.",
  retry_queued: "Your extraction is queued safely while we handle higher traffic.",
  starting: "Starting secure passport processing.",
  downloading_image: "Preparing the passport image for extraction.",
  extracting_passport_fields: "Extracting passport details from the passport image.",
  verifying_passport_fields: "Verifying the extracted passport details against the image.",
  saving_extraction_result: "Preparing the verified details for your review.",
  completed: "Passport details are ready for review.",
};

export function stageLabel(stage: string) {
  return PROCESSING_STAGE_LABELS[stage]
    ?? stage.replace(/_/g, " ").replace(/\b\w/g, (char) => char.toUpperCase());
}

export function submitErrorMessage(error: unknown) {
  if (isPublicApiError(error)) return error.message;
  if (isAxiosError(error)) {
    return extractApiErrorDetail(error.response?.data)
      ?? "Could not submit reviewed details. Please check the contact details.";
  }
  return "Could not submit reviewed details. Please try again.";
}

export function uploadPersistenceErrorMessage(error: unknown) {
  if (isPublicApiError(error)) return error.message;
  if (isAxiosError(error)) {
    const detail = extractApiErrorDetail(error.response?.data);
    if (error.response?.status && error.response.status >= 400 && error.response.status < 500) {
      return detail ?? "The passport pages were rejected. Check the file type and size, then try again.";
    }
    return detail
      ?? "We could not confirm that the passport pages were saved. Retry safely; the same upload will not create a duplicate.";
  }
  return "We could not confirm that the passport pages were saved. Check your connection and retry safely.";
}

export function NameInput({
  value,
  onChange,
  placeholder = "e.g. John Doe",
  autoFocus = false,
}: {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  autoFocus?: boolean;
}) {
  return (
    <div className="relative min-w-0">
      <User className="absolute left-4 top-3.5 h-5 w-5 text-slate-400" />
      <Input
        placeholder={placeholder}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-12 w-full min-w-0 rounded-xl border-slate-200 bg-white pl-12 text-base shadow-sm transition-colors placeholder:text-slate-400 focus-visible:ring-blue-600"
        required
        autoFocus={autoFocus}
      />
    </div>
  );
}

export function ContactSection({
  email,
  phone,
  departureCity,
  departureCities,
  onEmail,
  onPhone,
  onDepartureCity,
  title,
  emailRequired,
  phoneRequired,
  departureCityRequired = true,
}: {
  email: string;
  phone: string;
  departureCity: string;
  departureCities: string[];
  onEmail: (value: string) => void;
  onPhone: (value: string) => void;
  onDepartureCity: (value: string) => void;
  title: string;
  emailRequired?: boolean;
  phoneRequired?: boolean;
  departureCityRequired?: boolean;
}) {
  return (
    <div className="mt-6 border-t border-slate-100 pt-5">
      <h3 className="mb-3 text-base font-bold text-slate-900">{title}</h3>
      <div className="grid gap-4 sm:grid-cols-2">
        <ContactInput
          icon={<Mail className="h-5 w-5" />}
          label="Email"
          type="email"
          value={email}
          onChange={onEmail}
          required={emailRequired}
        />
        <ContactInput
          icon={<Phone className="h-5 w-5" />}
          label="WhatsApp active number"
          type="tel"
          value={phone}
          onChange={onPhone}
          required={phoneRequired}
        />
        {departureCities.length > 0 && (
          <DepartureCitySelect
            value={departureCity}
            cities={departureCities}
            onChange={onDepartureCity}
            className="sm:col-span-2"
            required={departureCityRequired}
          />
        )}
      </div>
    </div>
  );
}

export interface FamilyMember {
  reuseCompletion?: { binding: FamilyReuseBinding; result: CompletionResult & { source_submission_id: string } };
  replacementAssociated?: FamilyReuseBinding;
  localId: string;
  name: string;
  relation: string;
  gender: string;
  email: string;
  phone: string;
  baseCity: string;
  nearestDomesticAirport: string;
  staffCode: string;
  agentEmployeeType: AgentEmployeeType;
  agentEmployeeCode: string;
  designation: string;
  agencyDealershipName: string;
  mealPreference: string;
  customAnswers: Record<string, string>;
  customDetailAnswers: Record<string, string>;
  submission: PassportSubmission | null;
  reviewFields: Record<string, string>;
  visaSelfie: File | null;
  visaPhotoSource: "camera" | "file" | null;
  uploadIdempotencyKey: string;
  extractionNotice: string | null;
  canRetryExtraction: boolean;
}

export interface ExtractionWaitResult {
  submission: PassportSubmission;
  notice: string | null;
  retryAllowed: boolean;
}

export const PASSIVE_PROGRESS_STEPS: ReadonlySet<UploadFlowStep> = new Set([
  "BOOTSTRAP",
  "QUALIFIER_SELECT",
  "MODE_SELECT",
]);

export function activeUploadSessionId(
  mode: "single" | "family" | null,
  singleSessionId: string,
  familyMember: { uploadIdempotencyKey: string } | null,
): string | undefined {
  return mode === "family" ? familyMember?.uploadIdempotencyKey : singleSessionId;
}

function uploadRecoveryStorageKey(groupToken: string) {
  return `gct:upload-recovery:${groupToken}`;
}

function qualifierStorageKey(groupToken: string) {
  return `gct:qualifier-selection:${groupToken}`;
}

export function createIdempotencyKey() {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  if (
    typeof crypto !== "undefined"
    && typeof crypto.getRandomValues === "function"
  ) {
    const bytes = crypto.getRandomValues(new Uint8Array(32));
    return Array.from(
      bytes,
      (value) => value.toString(16).padStart(2, "0"),
    ).join("");
  }
  throw new Error(
    "Secure random number generation is required for passport upload.",
  );
}

export function readUploadRecoveryRecord(groupToken: string) {
  try {
    return parseUploadRecoveryRecord(
      window.sessionStorage.getItem(uploadRecoveryStorageKey(groupToken)),
    );
  } catch {
    return null;
  }
}

export function writeUploadRecoveryRecord(
  groupToken: string,
  record: ReturnType<typeof createUploadRecoveryRecord>,
) {
  try {
    window.sessionStorage.setItem(
      uploadRecoveryStorageKey(groupToken),
      serializeUploadRecoveryRecord(record),
    );
  } catch {
    // Recovery storage is optional in privacy-restricted in-app browsers.
    // Backend idempotency still protects the active in-memory attempt.
  }
}

export function readQualifierSelectionToken(groupToken: string) {
  try {
    return window.sessionStorage.getItem(qualifierStorageKey(groupToken));
  } catch {
    return null;
  }
}

export function writeQualifierSelectionToken(
  groupToken: string,
  selectionToken: string,
) {
  try {
    window.sessionStorage.setItem(
      qualifierStorageKey(groupToken),
      selectionToken,
    );
  } catch {
    // Session storage is an optional recovery aid. The in-memory bearer token
    // remains sufficient for the current upload attempt.
  }
}

export function clearQualifierSelectionToken(groupToken: string) {
  try {
    window.sessionStorage.removeItem(qualifierStorageKey(groupToken));
  } catch {
    // Storage may be unavailable in privacy-restricted in-app browsers.
  }
}

export function isPermanentQualifierRestoreError(error: unknown) {
  return PERMANENT_QUALIFIER_ERROR_STATUSES.has(apiErrorStatus(error) ?? 0);
}

export function isMissingSavedSubmissionError(error: unknown) {
  return MISSING_SUBMISSION_STATUSES.has(apiErrorStatus(error) ?? 0);
}

export interface UploadRecoveryRecord {
  version: 1;
  idempotencyKey: string;
  submissionId: string | null;
}

export type UploadRecoveryTarget =
  | { kind: "submission"; submissionId: string }
  | { kind: "attempt"; idempotencyKey: string };

export function createUploadRecoveryRecord(
  idempotencyKey: string,
  submissionId: string | null = null,
): UploadRecoveryRecord {
  return {
    version: 1,
    idempotencyKey,
    submissionId,
  };
}

export function parseUploadRecoveryRecord(
  serialized: string | null,
): UploadRecoveryRecord | null {
  if (!serialized) return null;

  try {
    const value: unknown = JSON.parse(serialized);
    if (!value || typeof value !== "object") return null;
    const candidate = value as Partial<UploadRecoveryRecord>;
    if (candidate.version !== 1) return null;
    if (
      typeof candidate.idempotencyKey !== "string"
      || candidate.idempotencyKey.length > MAX_IDEMPOTENCY_KEY_LENGTH
      || !IDEMPOTENCY_KEY_PATTERN.test(candidate.idempotencyKey)
    ) {
      return null;
    }
    if (
      candidate.submissionId !== null
      && (
        typeof candidate.submissionId !== "string"
        || candidate.submissionId.length < 1
        || candidate.submissionId.length > MAX_SUBMISSION_ID_LENGTH
      )
    ) {
      return null;
    }
    return {
      version: 1,
      idempotencyKey: candidate.idempotencyKey,
      submissionId: candidate.submissionId,
    };
  } catch {
    return null;
  }
}

export function serializeUploadRecoveryRecord(record: UploadRecoveryRecord) {
  return JSON.stringify(record);
}

export function uploadRecoveryTarget(
  record: UploadRecoveryRecord,
): UploadRecoveryTarget {
  if (record.submissionId) {
    return { kind: "submission", submissionId: record.submissionId };
  }
  return { kind: "attempt", idempotencyKey: record.idempotencyKey };
}

export function applyUploadReconciliation(
  record: UploadRecoveryRecord,
  submissionId: string | null,
): UploadRecoveryRecord {
  if (!submissionId) return record;
  return createUploadRecoveryRecord(record.idempotencyKey, submissionId);
}

